; C++ exception handling with __CxxFrameHandler4 data (as generated by Visual Studio 2019+)
;
; test_func: try { thrower(); return 1; } catch (...) { } return 77;
; The catch block continuation address is stored in the data as offset relative to function start,
; the IP to state map contains offsets relative to function start (compressed integers).
; Exit code of the program: 77 - exception was caught and execution continued at the right address
;
; assemble: nasm -f win64 fh4_test.asm
; link with: vcruntime140_1.dll (__CxxFrameHandler4), vcruntime140.dll (_CxxThrowException), kernel32.dll (ExitProcess)

default rel

extern __CxxFrameHandler4
extern _CxxThrowException
extern ExitProcess

section .text

global start
start:
        sub rsp, 0x28
.end_prolog:
        call test_func
        mov ecx, eax
        call ExitProcess
        int3
.end:

        align 16, int3
test_func:
        push rbx
.p1:
        sub rsp, 0x20
.p2:
        mov ebx, 1
        db 0x48, 0x81, 0xc3, 0, 0, 0, 0     ; add rbx, 0 (long encoding, the recompiled instruction is shorter, so the offsets change)
.try_start:
        call thrower
        nop
        mov ebx, 2
.try_end:
        mov eax, 1
        db 0x48, 0x81, 0xc3, 0, 0, 0, 0     ; add rbx, 0 (long encoding)
        jmp .epilog
.continuation:
        mov eax, 77
.epilog:
        add rsp, 0x20
        pop rbx
        ret
.end:

        align 16, int3
thrower:
        sub rsp, 0x38
.t1:
        mov dword [rsp+0x20], 42
        lea rcx, [rsp+0x20]
        lea rdx, [rel throw_info]
        call _CxxThrowException
        int3
.end:

        align 16, int3
catch_funclet:
        push rbp
.f1:
        sub rsp, 0x20
.f2:
        xor eax, eax        ; index of continuation address (continuation address is in the data)
        add rsp, 0x20
        pop rbp
        ret
.end:


section .rdata

        align 4
throw_info:
        dd 0                                    ; attributes
        dd 0                                    ; destructor
        dd 0                                    ; forward compatibility
        dd catchable_type_array wrt ..imagebase
catchable_type_array:
        dd 1
        dd catchable_type wrt ..imagebase
catchable_type:
        dd 1                                    ; simple type
        dd type_descriptor wrt ..imagebase
        dd 0, -1, 0                             ; this displacement
        dd 4                                    ; size
        dd 0                                    ; copy function

        align 4
uw_start:
        db 1, start.end_prolog - start, 1, 0
        db start.end_prolog - start, 0x42       ; sub rsp, 0x28
        db 0, 0

        align 4
uw_test_func:
        db 0x19                                 ; version 1, exception handler, termination handler
        db test_func.p2 - test_func, 2, 0
        db test_func.p2 - test_func, 0x32       ; sub rsp, 0x20
        db test_func.p1 - test_func, 0x30       ; push rbx
        dd __CxxFrameHandler4 wrt ..imagebase
        dd funcinfo wrt ..imagebase

        align 4
uw_thrower:
        db 1, thrower.t1 - thrower, 1, 0
        db thrower.t1 - thrower, 0x62           ; sub rsp, 0x38
        db 0, 0

        align 4
uw_catch_funclet:
        db 1, catch_funclet.f2 - catch_funclet, 2, 0
        db catch_funclet.f2 - catch_funclet, 0x32   ; sub rsp, 0x20
        db catch_funclet.f1 - catch_funclet, 0x50   ; push rbp

; FuncInfo4: header (unwind map, try block map, EHs), maps
funcinfo:
        db 0x38
        dd unwind_map wrt ..imagebase
        dd try_map wrt ..imagebase
        dd ip_map wrt ..imagebase

unwind_map:
        db 2 << 1                               ; 2 states
        db ((1 << 2) | 0) << 1                  ; state 0: no action, previous state -1
        db ((2 << 2) | 0) << 1                  ; state 1: no action, previous state -1

try_map:
        db 1 << 1                               ; 1 try block
        db 0 << 1, 0 << 1, 1 << 1               ; try low, try high, catch high
        dd handler_map wrt ..imagebase

handler_map:
        db 1 << 1                               ; 1 catch block
        db 0x10                                 ; catch (...), one continuation address relative to function start
        dd catch_funclet wrt ..imagebase
        dd (((test_func.continuation - test_func) << 4) | 7)

ip_map:
        db 2 << 1                               ; 2 entries
        dd (((test_func.try_start - test_func) << 4) | 7)
        db 1 << 1                               ; state 0
        dd (((test_func.try_end - test_func.try_start) << 4) | 7)
        db 0 << 1                               ; state -1


section .data

        align 8
type_descriptor:
        dq 0                                    ; vftable
        dq 0
        db ".H", 0                              ; int


section .pdata

        dd start wrt ..imagebase, start.end wrt ..imagebase, uw_start wrt ..imagebase
        dd test_func wrt ..imagebase, test_func.end wrt ..imagebase, uw_test_func wrt ..imagebase
        dd thrower wrt ..imagebase, thrower.end wrt ..imagebase, uw_thrower wrt ..imagebase
        dd catch_funclet wrt ..imagebase, catch_funclet.end wrt ..imagebase, uw_catch_funclet wrt ..imagebase
